require(['xwiki-tree'], function($) {
  'use strict';
  var containerSelector = '.sop-file-manager-location';
  var treeSelector = '.sop-file-manager-location-tree';
  var initializeTree = function(container) {
    if (container.data('fileManagerLocationInitialized')) {
      return;
    }
    container.data('fileManagerLocationInitialized', true);
    var treeElement = container.find(treeSelector);
    var hierarchyRadio = container.find('.sop-file-manager-location-hierarchy');
    var locationRadio = container.find('.sop-file-manager-location-value');
    var driveReference = container.attr('data-drive-reference');
    var finderPlaceholder = container.attr('data-finder-placeholder');
    var openFirstTwoLevels = function(tree) {
      var rootNode = tree.get_node($.jstree.root);
      $.each(rootNode && rootNode.children ? rootNode.children : [], function(index, childNodeId) {
        tree.open_node(childNodeId);
      });
    };
    treeElement
      .one('ready.jstree.sopFileManagerLocation', function(event, data) {
        var tree = data.instance;
        openFirstTwoLevels(tree);
        var selectedReference = locationRadio.val();
        if (!hierarchyRadio.prop('checked') && selectedReference && selectedReference !== driveReference) {
          var selectedNodeId = 'document:' + selectedReference;
          tree.openTo(selectedNodeId, function(node) {
            if (node && node.id === selectedNodeId) {
              tree.select_node(node);
            }
          });
        }
      })
      .on('changed.jstree.sopFileManagerLocation', function(event, data) {
        if (!data.selected || data.selected.length === 0) {
          return;
        }
        var selectedNode = data.instance.get_node(data.selected[0]);
        if (!selectedNode || !selectedNode.data || !selectedNode.data.id) {
          return;
        }
        locationRadio
          .val(selectedNode.data.id)
          .prop('checked', true)
          .trigger('change');
      })
      .xtree({
        core: {
          multiple: false
        },
        finder: {
          placeholder: finderPlaceholder
        }
      });
  };
  var initializeTrees = function() {
    $(containerSelector).each(function() {
      initializeTree($(this));
    });
  };
  $(initializeTrees);
  $(document).on('xwiki:dom:updated.sopFileManagerLocation', initializeTrees);
  $(document).on('focusin.sopFileManagerLocation click.sopFileManagerLocation', containerSelector, function() {
    initializeTree($(this));
  });
  $(document).on('click.sopFileManagerLocation', '.sop-file-manager-location-value', function() {
    var locationRadio = $(this);
    var container = locationRadio.closest(containerSelector);
    var tree = $.jstree.reference(container.find(treeSelector));
    locationRadio
      .val(container.attr('data-drive-reference'))
      .prop('checked', true);
    if (tree) {
      tree.deselect_all();
    }
  });
  $(document).on('change.sopFileManagerLocation', '.sop-file-manager-location-hierarchy', function() {
    if (!this.checked) {
      return;
    }
    var container = $(this).closest(containerSelector);
    var tree = $.jstree.reference(container.find(treeSelector));
    if (tree) {
      tree.deselect_all();
    }
  });
});

.sop-file-manager-location-option {
  display: block;
  font-weight: normal;
  margin: 0 0 .25em;
}
.sop-file-manager-location-picker {
  margin: .25em 0 0 1.5em;
  max-width: 44em;
}
.sop-file-manager-location-tree {
  max-height: 22em;
  overflow: auto;
}
